  "settings.modelProvider.help.contextWindow":
    "La capacidad de contexto que el modelo puede procesar a la vez, en tokens. ZCode la usa para gestionar el contexto.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.maxOutputTokens":
    "El número máximo de tokens que una única solicitud al modelo puede generar.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.inputModalities":
    "Define los tipos de contenido que el modelo puede recibir:\n\n- **Texto**: recibe contenido de texto. Obligatorio.\n- **Imágenes**: recibe contenido de imagen.\n- **Vídeo**: recibe contenido de vídeo.\n- **PDF**: recibe documentos PDF directamente.",
  "settings.modelProvider.help.outputModalities":
    "El tipo de contenido de las respuestas del modelo. Actualmente solo se soporta texto.",
  "settings.modelProvider.help.capabilities":
    "- **Salida estructurada**: soporta restricciones JSON Schema en campos, tipos y estructura de la salida.\n- **Búsqueda web nativa**: soporta la capacidad de búsqueda web integrada de la API del modelo.\n- **Mensajes de sistema a mitad de conversación**: soporta insertar instrucciones de sistema durante una conversación.\n\nNo actives capacidades que el modelo no soporta.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Define los niveles de razonamiento disponibles en el chat. **Deben estar ordenados de menor a mayor esfuerzo de razonamiento**.\nNo configures niveles de razonamiento que el modelo no soporta.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Usa una expresión CEL para mapear el nivel de razonamiento actual, `reasoningLevel`, a los campos de solicitud de la API del modelo. El objeto JSON devuelto por la expresión se fusiona en el cuerpo de la solicitud saliente.",
  "settings.modelProvider.help.advanced":
    "**MFJS tool schema**: activa la compatibilidad con Moonshot Flavored JSON Schema, usada comúnmente por la API del modelo Kimi de Moonshot. Actívalo solo cuando la API del modelo requiera este formato.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Coincide con la configuración recomendada usando el ID del modelo, la URL base y el formato de API. ZCode actualiza continuamente las recomendaciones y las sincroniza automáticamente contigo.\nCuando cambias un ajuste manualmente, ese ajuste pasa a gestión manual y deja de seguir las actualizaciones de recomendaciones; los demás ajustes siguen gestionados por la configuración inteligente.",
